function ParkourInput:TestKeyboradUpdate()
    local function CheckOneKey(name,key)
        if Input.GetKeyDown(key) then
            self[name] = 1
            return
        end
        if Input.GetKey(key) then
            self[name] = 2
            return
        end
        if Input.GetKeyUp(key) then
            self[name] = 3
            return
        end
        
        self[name] = 0
    end 
    
    CheckOneKey("jumpEvent",KeyCode.J)
    CheckOneKey("slideEvent",KeyCode.K)
    CheckOneKey("skillEvent",KeyCode.L)
end


