function ParkourInput:AfterLogic()
    local function ResetOneKey(name)
        if self[name] == 3 then
            self[name] = 0
        elseif self[name] == 1 then
            self[name] = 2
        end
    end
    
    ResetOneKey("jumpEvent")
    ResetOneKey("slideEvent")
    ResetOneKey("skillEvent")
end


